import javax.tools.*;import java.nio.file.*;import java.net.*;import java.util.*;
/** Production album controls/hierarchy with host view adapters; not native Android rendering. */
public final class ArchiveUiRegression {
 static void write(Path dir,List<String> files,String path,String value)throws Exception{ExposurePipelineRegression.write(dir,files,path,value);}
 public static void main(String[] args)throws Exception{
  Path root=Paths.get(args[0]),dir=root.resolve("build/archive-ui-tests"),classes=dir.resolve("classes");Files.createDirectories(classes);List<String> files=new ArrayList<>();
  write(dir,files,"android/graphics/Color.java","package android.graphics;public class Color{public static final int TRANSPARENT=0;}");
  write(dir,files,"android/graphics/drawable/InsetDrawable.java","package android.graphics.drawable;public class InsetDrawable{public int top,bottom,left,right;public InsetDrawable(Object d,int l,int t,int r,int b){left=l;top=t;right=r;bottom=b;}}");
  write(dir,files,"android/util/TypedValue.java","package android.util;public class TypedValue{public static final int COMPLEX_UNIT_DIP=1;}");
  write(dir,files,"android/text/TextUtils.java","package android.text;public class TextUtils{public static class TruncateAt{public static final Object END=new Object();}}");
  write(dir,files,"android/view/View.java","package android.view;public class View{public Object params,background;public int minimum;public boolean selected;public int[] padding;public void setBackground(Object o){background=o;}public void setBackgroundColor(int n){background=n;}public void setPadding(int l,int t,int r,int b){padding=new int[]{l,t,r,b};}public void setSelected(boolean b){selected=b;}public void setContentDescription(String s){}public void setTooltipText(String s){}}");
  write(dir,files,"android/widget/TextView.java","package android.widget;public class TextView extends android.view.View{public float size;public int unit,maxLines,color;public String text;public Runnable action;public void setTextSize(float n){size=n;unit=2;}public void setTextSize(int u,float n){unit=u;size=n;}public void setMaxLines(int n){maxLines=n;}public void setTextColor(int n){color=n;}public void setEllipsize(Object n){}}");
  write(dir,files,"android/widget/LinearLayout.java","package android.widget;import java.util.*;import android.view.View;public class LinearLayout extends View{public List<View> children=new ArrayList<>();public int getChildCount(){return children.size();}public void addView(View v,LayoutParams p){children.add(v);v.params=p;}public static class LayoutParams{public int width,height,leftMargin;public float weight;public LayoutParams(int w,int h,float f){width=w;height=h;weight=f;}}}");
  write(dir,files,"android/widget/ListView.java","package android.widget;public class ListView extends android.view.View{public LinearLayout header;public boolean focus;public ListView(Object c){}public void setDivider(Object d){}public void setDividerHeight(int h){}public void setClipToPadding(boolean b){}public void setItemsCanFocus(boolean b){focus=b;}public void addHeaderView(LinearLayout v,Object data,boolean selectable){header=v;}}");
  write(dir,files,"com/silverroom/camera/Controls.java","package com.silverroom.camera;class Controls{static int PANEL=1,INK=2,AMBER=3,MUTED=4;static int tone(int n){return n;}}");
  write(dir,files,"com/silverroom/camera/MainActivity.java","package com.silverroom.camera;import android.widget.*;class MainActivity{int dp(int n){return n;}Object bg(int c,int r,int s){return new Object();}TextView button(String text,Runnable action){TextView v=new TextView();v.text=text;v.action=action;v.minimum=48;return v;}TextView text(String text,int sp,int color){TextView v=new TextView();v.text=text;v.setTextSize(sp);v.setTextColor(color);return v;}}");
  write(dir,files,"com/silverroom/camera/AlbumProbe.java",probe());
  for(String n:new String[]{"ArchiveUi","ArchiveLayout","AppTheme"})files.add(root.resolve("src/com/silverroom/camera/"+n+".java").toString());
  List<String> options=new ArrayList<>(Arrays.asList("--release","8","-encoding","UTF-8","-d",classes.toString()));options.addAll(files);if(ToolProvider.getSystemJavaCompiler().run(null,null,null,options.toArray(new String[0]))!=0)throw new AssertionError("Album UI fixture compile");
  try(URLClassLoader loader=new URLClassLoader(new URL[]{classes.toUri().toURL()},null)){try{for(Object line:(List<?>)loader.loadClass("com.silverroom.camera.AlbumProbe").getMethod("run").invoke(null))System.out.println("PASS "+line);}catch(java.lang.reflect.InvocationTargetException e){throw new AssertionError("Production album UI",e.getCause());}}
 }
 static String probe(){return "package com.silverroom.camera;import java.util.*;import android.view.*;import android.widget.*;import android.graphics.drawable.*;public class AlbumProbe{public static List<String> run(){List<String> passed=new ArrayList<>();MainActivity a=new MainActivity();int[] calls={0};TextView command=ArchiveUi.command(a,\"导入\",\"导入相册\",()->calls[0]++);InsetDrawable surface=(InsetDrawable)command.background;if(command.minimum<48||surface.top!=6||surface.bottom!=6||command.maxLines!=1)throw new AssertionError(\"compact surface/full target\");command.action.run();if(calls[0]!=1)throw new AssertionError(\"lost action\");passed.add(\"Compact album buttons inset only their visual backgrounds while retaining 48dp targets and original actions\");TextView icon=ArchiveUi.icon(a,\"‹\",\"返回\",()->{});if(icon.unit!=1||icon.size!=28||!icon.background.equals(0))throw new AssertionError(\"oversized icon surface\");passed.add(\"Header icons have transparent backgrounds and fixed dp glyph size independent of font enlargement\");for(int width:new int[]{296,336,408})for(float font:new float[]{1,1.3f,2}){int count=ArchiveLayout.columns(width,font);if(count<1||count>3||width/count<Math.min(width,104*font))throw new AssertionError(\"grid too dense\");int height=ArchiveLayout.tool(font);if(height<48||height-12<13*font*1.2+8||(width-24)/4f<2*13*font+12)throw new AssertionError(\"buttons overlap or clip\");LinearLayout actions=new LinearLayout();for(int i=0;i<4;i++)ArchiveUi.append(a,actions,ArchiveUi.command(a,\"移卷\",\"移卷\",()->{}),height);for(int i=0;i<4;i++){LinearLayout.LayoutParams p=(LinearLayout.LayoutParams)actions.children.get(i).params;if(p.width!=0||p.height!=height||p.weight!=1||p.leftMargin!=(i==0?0:8))throw new AssertionError(\"spacing\");}}passed.add(\"Album controls and adaptive photo columns keep readable spacing at 320/360/432dp and 100/130/200 percent fonts\");LinearLayout root=new LinearLayout(),header=new LinearLayout();ListView list=ArchiveUi.body(a,root,header);LinearLayout.LayoutParams body=(LinearLayout.LayoutParams)list.params;if(root.children.size()!=1||list.header!=header||body.height!=0||body.weight!=1||!list.focus)throw new AssertionError(\"header must scroll within body\");passed.add(\"Search, tools and roll summary belong to the scrolling list header rather than fixed-height rows above it\");TextView tab=ArchiveUi.tab(a,\"胶卷\",true,()->{});if(!tab.selected||tab.color!=Controls.AMBER)throw new AssertionError(\"tab selection\");passed.add(\"Album segments expose the selected page without adding another large filled button frame\");return passed;}}";}
}
